        x[i, :s.numel()] = s
        mask[i, :s.numel()] = 1
    return x, mask


def train_one_epoch(model, xs, ys, lr=0.1, steps=200):
    opt = torch.optim.SGD(model.parameters(), lr=lr)   # 修 1: 少了括号
